// Plan lines are built from parts joined by " · ": each part is translated on its own.
const PLAN = { Starter: 'סטארטער', Pro: 'פרא', Elite: 'עליט', Ultimate: 'אלטימעט' };
const PARTS = [
  [/^(\d+) bots? at once \((\d+) running\)$/, '$1 באטס אויפאמאל ($2 לויפן)'],
  [/^checks once a day$/, 'קוקט נאך איינמאל א טאג'], [/^checks every (\d+) min$/, 'קוקט נאך יעדע $1 מינוט'],
  [/^practice account$/, 'פראקטיק אקאונט'], [/^real accounts$/, 'עכטע אקאונטס'],
  [/^(\d+) plain-English builds a day$/, '$1 פשוט-ענגלישע בויען א טאג'],
  [/^marketplace browsing$/, 'מארקעטפלעיס דורכקוקן'], [/^marketplace browsing and copying$/, 'מארקעטפלעיס דורכקוקן און קאפירן'],
  [/^(\d+) signals a day$/, '$1 סיגנאלן א טאג'], [/^no automatic trades$/, 'אן אויטאמאטישע טרעידס'],
  [/^automatic trades on the practice account$/, 'אויטאמאטישע טרעידס אויפן פראקטיק אקאונט'], [/^automatic trades on real accounts$/, 'אויטאמאטישע טרעידס אויף עכטע אקאונטס'],
  [/^standard engine$/, 'געווענליכער אינזשין'], [/^custom engines$/, 'אייגענע אינזשינס'],
  [/^(\d+) connected agents?$/, '$1 פארבונדענע אגענטן'], [/^practice orders only$/, 'נאר פראקטיק ארדערס'],
  [/^real orders with your approval$/, 'עכטע ארדערס מיט אייער באשטעטיגונג'], [/^automatic real orders within your limits$/, 'אויטאמאטישע עכטע ארדערס אינערהאלב אייערע גרעניצן'],
  [/^(\d+) requests a minute$/, '$1 פארלאנגען א מינוט'], [/^regular hours$/, 'געווענליכע שעות'], [/^extended hours$/, 'אויך אויסער די געווענליכע שעות'],
];
const part = s => { for (const [re, rep] of PARTS) if (re.test(s)) return s.replace(re, rep); return s; };
export const patterns = [
  [/^Your plan \((\w+)\): (.+?)\.?$/, (m, plan, rest) => `אייער פלאן (${PLAN[plan] || plan}): ${rest.split(' · ').map(part).join(' · ')}.`],
  [/^(\d+) of (\d+)$/, '$1 פון $2'],
  [/^Step (\d+) of (\d+)$/, 'שריט $1 פון $2'],
  [/^My bots \((\d+)\)$/, 'מיינע באטס ($1)'],
  [/^Open \((\d+)\)$/, 'אפן ($1)'],
  [/^Remove ([A-Z0-9./-]+)$/, 'נעמט אראפ $1'],
  [/^(\d+) sleeves? · (\d+) steps? · (\d+) leveraged \+ (\d+) ETF\/stock tickers$/, '$1 סליווס · $2 שריט · $3 לעווערידזשד + $4 ETF/סטאק טיקערס'],
  [/^Equity (\$[\d,.]+)$/, 'עקוויטי $1'],
  [/^(\d+) accounts?$/, '$1 אקאונטס'],
  [/^Signals for (.+)$/, 'סיגנאלן פאר $1'],
  [/^Agents on (.+)$/, 'אגענטן אויף $1'],
  [/^Today: (\d+) agent orders?, (\$[\d,.]+)\. Market (open|closed)\.$/, (m, n, usd, st) => `היינט: ${n} אגענט ארדערס, ${usd}. דער מארקעט איז ${st === 'open' ? 'אפן' : 'פארמאכט'}.`],
  [/^(\d+) stocks scanned · (.+)\. Also in the$/, '$1 סטאקס דורכגעקוקט · $2. אויך אין'],
  [/^This account holds only cash \((\$[\d,.]+)\)\. Try “What if I added…” above to see the risk of a portfolio before you buy anything, or practice with a$/, 'דער אקאונט האלט נאר קעש ($1). פרובירט "וואס וואלט געווען ווען איך לייג צו…" אויבן, צו זען די ריזיקע פון א פארטפאליא איידער איר קויפט עפעס, אדער פראקטיצירט מיט א'],
  [/^RSI (\d+): neither overbought nor oversold\.$/, 'RSI $1: נישט איבערגעקויפט און נישט איבערפארקויפט.'],
  [/^(-?[\d.]+%) from the 52-week high, ([\d.]+%) above the low\.$/, '$1 פון דעם 52-וואכיגן רעקארד, $2 העכער דעם נידעריגסטן.'],
  [/^(\$[\d,]+) in today's dollars$/, '$1 אין היינטיגע דאלערס'],
  [/^growth (\$[\d,]+)$/, 'וואוקס $1'],
  [/^to age (\d+)$/, 'ביז $1 יאר'],
  [/^At (\d+)$/, 'ביי $1'],
  [/^Putting (\$[\d,]+) a month in a Roth gives about$/, 'אריינלייגן $1 א חודש אין א ראט גיט בערך'],
  [/^a month after tax in retirement; the same take-home pay in a Traditional IRA \((\$[\d,]+) a month before tax\) gives about$/, 'א חודש נאך טעקס אין די עלטערע יארן; די זעלבע נעטא הכנסה אין א טראדיציאנעלע IRA ($1 א חודש פאר טעקס) גיט בערך'],
  [/^(\$[\d,]+) tax-deductible$/, '$1 מעג מען אראפרעכענען פון טעקס'],
  [/^Equalize positions in (.+)$/, 'גלייכט אויס די פאזישאנס אין $1'],
  [/^After hours · opens in (.+)$/, 'נאך די שעות · עפנט זיך אין $1'],
  [/^Pre-market · opens in (.+)$/, 'פאר דעם מארקעט · עפנט זיך אין $1'],
  [/^Market open · closes in (.+)$/, 'דער מארקעט איז אפן · פארמאכט זיך אין $1'],
  [/^Market closed · opens in (.+)$/, 'דער מארקעט איז פארמאכט · עפנט זיך אין $1'],
  [/^(\d+) more signals today with a higher plan\.$/, 'נאך $1 סיגנאלן היינט מיט א העכערן פלאן.'],
  [/^([\d,]+) historical scenarios over (\d+) symbols$/, '$1 היסטארישע סצענארן איבער $2 סימבאלן'],
  [/^National average rates \(Freddie Mac\); lenders in (.+?) quote around these depending on your credit and down payment\. (.*)$/, 'דורכשניט ראטעס אין לאנד (Freddie Mac); די בענק אין $1 געבן בערך די ראטעס, לויט אייער קרעדיט און אייער דאון פעימענט. $2'],
  [/^Each holding gets about$/, 'יעדער האלדינג באקומט בערך'],
  [/^Dow 30 \((\d+)\)$/, 'Dow 30 ($1)'],
];
